#!/bin/sh
# Generated by FWShift: the rule tables of one Cisco Meraki MX network, put through the Dashboard API (v1).
# Read the report first: what is not written is listed there. Each put replaces the whole table.
# Usage: MERAKI_API_KEY=... NETWORK_ID=N_... [MERAKI_BASE=https://api.meraki.com/api/v1] [DRY_RUN=1] sh this-file
# DRY_RUN=1 only writes the bodies, and needs no key. The backups (before-*.json) end in the fixed default rule of the
# MX: to put a backup back, remove that last rule (comment "Default rule") from its rules first.
set -eu
OUT="${OUT:-meraki-$(date +%Y%m%d%H%M%S)}"
mkdir -p "$OUT"
api() {  # api METHOD PATH [BODY-FILE]
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Content-Type: application/json' -H 'Accept: application/json' --data-binary @"$3" "$MERAKI_BASE$2")
    else
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Accept: application/json' "$MERAKI_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/last.json"; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/last.hdr"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/last.json" >&2; return 1 ;;
    esac
  done
}
cat > "$OUT/l3FirewallRules.json" <<'FWSHIFT_EOF'
{
 "rules": [
  {
   "comment": "nothing to the bad networks",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/0",
   "destPort": "Any",
   "destCidr": "192.0.2.66/32,203.0.113.0/25",
   "syslogEnabled": true
  },
  {
   "comment": "WAN to DMZ #3",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/0",
   "destPort": "Any",
   "destCidr": "0.0.0.0/0",
   "syslogEnabled": true
  },
  {
   "comment": "WAN to LAN #1",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/0",
   "destPort": "Any",
   "destCidr": "0.0.0.0/0",
   "syslogEnabled": true
  },
  {
   "comment": "the source blocks what no rule matches",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  }
 ],
 "syslogDefaultRule": false
}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
