#   Admins out by SSH: the source of the rule is in zone LAN, and the MX names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   LAN to WAN #3: the source of the rule is in zone LAN, and the MX names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   LAN to WAN #5: the source of the rule is in zone LAN, and the MX names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   Web server from the internet: the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
#   Mail from partners: the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
